import {
  INPUT_HOLD_FRAMES,
  MAX_INPUT_MESSAGES_PER_SECOND,
  validateInputMessage,
  type InputContext,
  type InputRejection,
} from "@pirate-sea-race/protocol";
import { NEUTRAL_INPUT, quantizeAxis, STEPS_PER_SECOND, type PlayerInput } from "@pirate-sea-race/simulation";

export type DropReason = InputRejection | "rate-limited";

/** A protocol validator: `validateInputMessage` for world input, `validateDuelInputMessage` for duel input. */
export type InputValidator<T extends { readonly seq: number }> = (
  message: unknown,
  context: InputContext,
) => { ok: true; input: T } | { ok: false; reason: InputRejection };

/**
 * The admission both input gates share, so their limits cannot drift apart: at most MAX_INPUT_MESSAGES_PER_SECOND
 * messages in each window of STEPS_PER_SECOND room ticks, then the protocol's validation (size, schema, a sequence
 * number above the last accepted one, the future-frame limit). Every drop is counted by reason.
 */
export class InputAdmission<T extends { readonly seq: number }> {
  private lastAcceptedSeq = 0;
  private windowStart = 0;
  private windowCount = 0;
  readonly dropped: Record<DropReason, number> = {
    "rate-limited": 0,
    oversized: 0,
    malformed: 0,
    "stale-sequence": 0,
    "future-frame": 0,
  };

  constructor(private readonly validate: InputValidator<T>) {}

  /**
   * Takes one untrusted message at room tick `tick` (for the rate window) when the server's frame is `serverFrame`
   * (for the future-frame limit). Returns the accepted message, or why it was dropped.
   */
  admit(message: unknown, tick: number, serverFrame: number): { ok: true; input: T } | { ok: false; reason: DropReason } {
    if (tick - this.windowStart >= STEPS_PER_SECOND) {
      this.windowStart = tick;
      this.windowCount = 0;
    }
    if (++this.windowCount > MAX_INPUT_MESSAGES_PER_SECOND) return this.drop("rate-limited");
    const result = this.validate(message, { lastAcceptedSeq: this.lastAcceptedSeq, serverFrame });
    if (!result.ok) return this.drop(result.reason);
    this.lastAcceptedSeq = result.input.seq;
    return result;
  }

  private drop(reason: DropReason): { ok: false; reason: DropReason } {
    this.dropped[reason]++;
    return { ok: false, reason };
  }
}

/**
 * One client's input channel on the server: it admits messages under the rate cap, validates them against the
 * protocol and the client's last sequence, and holds the latest accepted intent for the simulation. A held input
 * lapses to neutral when no fresh one arrives within INPUT_HOLD_FRAMES (§15). World logic reads input only every
 * third frame, so a button pressed at any point since the last world step is latched until the next one (see
 * `worldStepTaken`): a quick tap released between two world steps still counts.
 */
export class InputGate {
  private readonly admission = new InputAdmission(validateInputMessage);
  private held: PlayerInput = NEUTRAL_INPUT;
  private heldAtFrame = 0;
  /** Buttons seen in any accepted message since the last world step. */
  private latchedButtons = 0;

  /** Messages dropped, by reason. */
  get dropped(): Record<DropReason, number> {
    return this.admission.dropped;
  }

  /** Takes one untrusted message at the server's current frame. Returns why it was dropped, or undefined. */
  receive(message: unknown, serverFrame: number): DropReason | undefined {
    // The match room ticks once per frame, so its frame is also the rate window's clock.
    const result = this.admission.admit(message, serverFrame, serverFrame);
    if (!result.ok) return result.reason;
    this.held = {
      buttons: result.input.buttons,
      moveX: quantizeAxis(result.input.moveX),
      moveY: quantizeAxis(result.input.moveY),
    };
    this.heldAtFrame = serverFrame;
    this.latchedButtons |= result.input.buttons;
    return undefined;
  }

  /**
   * Whether the client has sent nothing the simulation could use at `frame`: its held input has lapsed and no button
   * is latched. The match room then gives the simulation no input for the ship at all, rather than neutral input, so a
   * stall cannot release the throttle a moored ship keeps (see `StepInputs`).
   */
  lapsedAt(frame: number): boolean {
    return frame - this.heldAtFrame > INPUT_HOLD_FRAMES && this.latchedButtons === 0;
  }

  /** The intent the simulation uses for `frame`: the held input, plus any button latched since the last world step. */
  inputAt(frame: number): PlayerInput {
    const held = frame - this.heldAtFrame > INPUT_HOLD_FRAMES ? NEUTRAL_INPUT : this.held;
    const buttons = held.buttons | this.latchedButtons;
    return buttons === held.buttons ? held : { ...held, buttons };
  }

  /** Called after each world step has read `inputAt`: latched buttons have been seen and are released. */
  worldStepTaken(): void {
    this.latchedButtons = 0;
  }
}
import { z } from "zod";

export const MessageType = {
  /** Client → server: the player's held intent. */
  Input: "input",
} as const;

/** Largest input message accepted, measured as its JSON encoding. A valid one is well under 100 bytes. */
export const MAX_INPUT_MESSAGE_BYTES = 128;
/** How far ahead of the server's current frame an input's frame tag may be (§15: reject future-frame spam). */
export const MAX_INPUT_LEAD_FRAMES = 30;
/** Input messages a client may send per second of match time before the server drops the rest. */
export const MAX_INPUT_MESSAGES_PER_SECOND = 60;
/** The server repeats a held input for at most this many frames (250 ms) without a fresh one, then goes neutral. */
export const INPUT_HOLD_FRAMES = 15;

export const MAX_SEQUENCE = 2 ** 31 - 1;

/**
 * Button bits (§8). Interact (E) docks a ship near a dock; grapple (J, protocol v5) asks the encounter rules to start a
 * grapple (§6), whose target the server chooses; fruit (F held, protocol v9) eats the fruit at the pedestal where the
 * ship is moored (§9). The other bits are reserved for world actions.
 */
export const Buttons = {
  Interact: 1 << 0,
  Grapple: 1 << 1,
  Fruit: 1 << 2,
} as const;

/**
 * One frame-tagged input (§16): a strictly increasing sequence number, the client's estimate of the server frame,
 * a button bit field and movement axes bounded to [-1, 1]. Axes outside the range are rejected, not clamped.
 *
 * At sea (protocol v3) the axes steer a ship: `moveX` turns (positive clockwise, to starboard) and `moveY` is the
 * throttle, negative ahead (up on a keyboard) and positive to brake, then reverse slowly from a stop.
 */
export const inputMessageSchema = z.strictObject({
  seq: z.int().min(1).max(MAX_SEQUENCE),
  frame: z.int().min(0).max(MAX_SEQUENCE),
  buttons: z.int().min(0).max(0xffff),
  moveX: z.number().min(-1).max(1),
  moveY: z.number().min(-1).max(1),
});

export type InputMessage = z.infer<typeof inputMessageSchema>;

export type InputRejection = "oversized" | "malformed" | "stale-sequence" | "future-frame";

export type InputValidation = { ok: true; input: InputMessage } | { ok: false; reason: InputRejection };

/** What the server knows when a message arrives: the last sequence it accepted from this client, and its frame. */
export interface InputContext {
  readonly lastAcceptedSeq: number;
  readonly serverFrame: number;
}

/** Size of a decoded message as JSON, or undefined when it cannot be encoded (cycles, BigInt). */
export function encodedSize(message: unknown): number | undefined {
  try {
    const json = JSON.stringify(message);
    return json === undefined ? undefined : utf8Length(json);
  } catch {
    return undefined;
  }
}

function utf8Length(text: string): number {
  let bytes = 0;
  for (const char of text) {
    const code = char.codePointAt(0)!;
    bytes += code < 0x80 ? 1 : code < 0x800 ? 2 : code < 0x10000 ? 3 : 4;
  }
  return bytes;
}

/** Validates an untrusted input message against its schema and the sender's sequence and the server clock. */
export function validateInputMessage(message: unknown, context: InputContext): InputValidation {
  const size = encodedSize(message);
  if (size === undefined) return { ok: false, reason: "malformed" };
  if (size > MAX_INPUT_MESSAGE_BYTES) return { ok: false, reason: "oversized" };
  const parsed = inputMessageSchema.safeParse(message);
  if (!parsed.success) return { ok: false, reason: "malformed" };
  const input = parsed.data;
  if (input.seq <= context.lastAcceptedSeq) return { ok: false, reason: "stale-sequence" };
  if (input.frame > context.serverFrame + MAX_INPUT_LEAD_FRAMES) return { ok: false, reason: "future-frame" };
  return { ok: true, input };
}
/** The client and server must speak the same protocol version to join (§17). Bump it on any message change. */
export const PROTOCOL_VERSION = 10;

/** The Colyseus room name of a match. */
export const MATCH_ROOM = "match";
export * from "./version.js";
export * from "./join.js";
export * from "./input.js";
export * from "./testPlacement.js";
export * from "./duel.js";
export * from "./rubbings.js";
export * from "./match.js";
export * from "./ruins.js";
export * from "./fruits.js";
export * from "./journal.js";
import { MAX_INPUT_LEAD_FRAMES, MessageType, type InputMessage } from "@pirate-sea-race/protocol";
import { STEPS_PER_SECOND } from "@pirate-sea-race/simulation";
import { NEUTRAL_HELM, type Helm } from "./keyboard.js";

/** Resend a held input this often, well inside the server's 250 ms hold window. */
const REFRESH_MS = 100;
/** Never tag an input further ahead than half the server's future-frame window. */
const MAX_ESTIMATE_LEAD = Math.floor(MAX_INPUT_LEAD_FRAMES / 2);

/** The client's estimate of the server's current frame: the last patched frame plus the time since it arrived. */
export function estimateServerFrame(patchedFrame: number, patchedAt: number, now: number): number {
  const elapsed = Math.max(0, Math.floor(((now - patchedAt) * STEPS_PER_SECOND) / 1000));
  return patchedFrame + Math.min(elapsed, MAX_ESTIMATE_LEAD);
}

export interface InputChannel {
  send(type: string, message: InputMessage): void;
}

/** Sends the player's intent: on every change, and repeated while a key is held. */
export class InputSender {
  private seq = 0;
  private last: Helm = NEUTRAL_HELM;
  private lastSentAt = Number.NEGATIVE_INFINITY;
  private patchedFrame = 0;
  private patchedAt = 0;

  constructor(private readonly channel: InputChannel) {}

  observeFrame(frame: number, now: number): void {
    if (frame !== this.patchedFrame) {
      this.patchedFrame = frame;
      this.patchedAt = now;
    }
  }

  update(helm: Helm, now: number): void {
    const changed = helm.moveX !== this.last.moveX || helm.moveY !== this.last.moveY || helm.buttons !== this.last.buttons;
    const held = helm.moveX !== 0 || helm.moveY !== 0 || helm.buttons !== 0;
    if (!changed && !(held && now - this.lastSentAt >= REFRESH_MS)) return;
    this.channel.send(MessageType.Input, {
      seq: ++this.seq,
      frame: estimateServerFrame(this.patchedFrame, this.patchedAt, now),
      buttons: helm.buttons,
      moveX: helm.moveX,
      moveY: helm.moveY,
    });
    this.last = helm;
    this.lastSentAt = now;
  }
}

