502	  override async onCreate(options: unknown): Promise<void> {
503	    // Only a token-carrying request creates a match. A join by code reaches here only when its match filled up or
504	    // closed after authorizeEntry admitted it (joinOrCreate then falls back to create).
505	    const parsed = createMatchOptionsSchema.safeParse(options);
506	    if (!parsed.success) throw new ServerError(ErrorCode.MATCHMAKE_INVALID_CRITERIA, MATCH_UNAVAILABLE_MESSAGE);
507	    this.createToken = parsed.data.createToken;
508	    const code = await this.allocateCode();
509	    this.tuning = this.matchTuning();
510	    this.encounterConfig = createEncounterConfig({ map: this.config.map, rules: this.tuning.encounters });
511	    this.encounters = createEncounterState(this.encounterConfig);
512	    // One private master secret per match; each system gets its own seed derived from it, never the match code (§3, §16).
513	    this.secret = this.tuning.masterSecret();
514	    this.simulation = createMatchState(this.seedOf("world"));
515	    this.ledger = createMatchLedger({ map: this.config.map, seed: this.seedOf("ledger"), rules: this.tuning.objectives, layout: this.tuning.sourceLayout });
516	    this.finalIsland = finalIslandOf(this.config.map, this.tuning.finalSocketSecret ?? this.seedOf("final-socket"));
517	    // Every source starts locked behind its island's ruin (§3); only a test opens islands from the start.
518	    const dealt = createMatchRuins({
519	      islands: ruinIslandsOf(this.ledger),
520	      seed: (attempt) => this.seedOf(attempt === 0 ? "ruins" : `ruins:${attempt}`),
521	      settings: this.tuning.testRuins,
522	    });
523	    this.ruins = dealt.ruins;
524	    this.ledger = openIslandsInLedger(this.ledger, dealt.openIslands);
525	    // §9's fruit, dealt onto the pedestals from the fruit's own seed (only a test pins the deal).
526	    this.pedestals = pedestalSites(this.config.map);
527	    this.fruits = createMatchFruits({ sites: this.pedestals, seed: this.seedOf("fruit"), layout: this.tuning.testFruits });
528	    for (const site of this.pedestals) {
529	      const marker = new PedestalMarkerSchema();
530	      marker.island = site.island;
531	      marker.dock = site.dock;
532	      marker.x = site.x;
533	      marker.y = site.y;
534	      this.state.pedestals.set(site.id, marker);
535	    }
536	    for (const island of Object.keys(this.ruins.ruins)) {
537	      const marker = new RuinMarkerSchema();
538	      const centre = islandCentre(this.config.map, Number(island));
539	      marker.island = Number(island);
540	      marker.x = centre.x;
541	      marker.y = centre.y;
542	      this.state.ruins.set(island, marker);
543	    }
544	    this.flowConfig = matchConfigFor(this.tuning);
545	    this.flow = createFlowState(this.flowConfig);
546	    this.state.code = code;
