563	    });
564	    // A duel's messages reach only its machine, and only from its two fighters.
565	    this.onMessage(DuelMessageType.Input, (client, message: unknown) => this.duelOfSession(client.sessionId)?.machine.receiveInput(client.sessionId, message));
