1173	      case "claim-interrupted": {
1174	        const notice = this.noticesOf(event.playerId);
1175	        notice.claimInterrupt = event.reason;
1176	        notice.claimInterruptAt = event.tick;
1177	        return undefined;
1178	      }
1179	      case "claim-started":
1180	        this.noticesOf(event.playerId).claimInterrupt = "";
1181	        return undefined;
1182	      case "protection-ended":
1183	        // §6: claiming ends protection; the encounter rules hear it on the next tick.
1184	        this.protectionEndedNext.set(event.playerId, "claim");
