1194	  /**
1195	   * The accomplishments of this tick (§2's results), read from the ledger, which alone moves rubbings and gold: each
1196	   * rubbing that changed hands since the last tick (from a source: collected; from a cache: a cache claimed; from one
1197	   * player to another: a theft and a loss; from a player into a cache: a loss), each balance that changed, and each
1198	   * island a player first moors at.
1199	   */
1200	  private reportAccomplishments(_tick: number): void {
1201	    // Unknown ids are dropped with every other report's, before the flow's step (`knownFlowReports`).
1202	    const report = (entry: FlowReport) => this.flowReports.push(entry);
1203	    for (const rubbing of this.ledger.rubbings) {
1204	      const before = this.lastLocations.get(rubbing.id);
1205	      this.lastLocations.set(rubbing.id, rubbing.location);
1206	      // The first tick in play only records where each rubbing is.
1207	      if (before === undefined) continue;
1208	      const from = holderOf(before);
1209	      const to = holderOf(rubbing.location);
1210	      if (from === to) continue;
1211	      if (from === undefined && to !== undefined) {
1212	        if (before.kind === "source") report({ kind: "collected", playerId: to });
1213	        else if (before.kind === "cache") report({ kind: "cache-claimed", playerId: to });
1214	      } else if (from !== undefined && to !== undefined) {
1215	        report({ kind: "stole", playerId: to });
1216	        report({ kind: "lost", playerId: from });
1217	      } else if (from !== undefined) {
1218	        report({ kind: "lost", playerId: from });
1219	      }
1220	    }
1221	    for (const player of this.ledger.players) {
1222	      if (this.reportedGold.get(player.id) === player.gold) continue;
1223	      this.reportedGold.set(player.id, player.gold);
1224	      report({ kind: "gold", playerId: player.id, gold: player.gold });
1225	    }
1226	    for (const ship of this.simulation.ships) {
1227	      const island = ship.dock === NOT_DOCKED ? -1 : (this.config.map.docks[ship.dock]?.island ?? -1);
1228	      if (island < 0 || this.visited.has(`${ship.id}:${island}`)) continue;
1229	      this.visited.add(`${ship.id}:${island}`);
1230	      report({ kind: "island-visited", playerId: ship.id, island: String(island) });
1231	    }
1232	  }
