1234	  /**
1235	   * §2's match flow, one world tick: the joins, leaves and start requests since the last tick, this tick's
1236	   * accomplishments and the claim's end, in that order. Reports naming a player the flow does not know are dropped
1237	   * first (`knownFlowReports`: the match module throws on them), and counted for tests.
1238	   */
1239	  private stepFlow(tick: number, claimEnd?: FlowReport): void {
1240	    const reports = this.flowReports;
1241	    this.flowReports = [];
1242	    if (claimEnd !== undefined) reports.push(claimEnd);
1243	    this.stepFlowWith(tick, reports);
