1253	
1254	  private applyFlowEvent(event: FlowEvent): void {
1255	    switch (event.kind) {
1256	      case "start-refused":
1257	        this.clients.get(event.playerId)?.send(MatchMessageType.StartRefused, { reason: event.reason } satisfies StartRefusedMessage);
1258	        return;
1259	      // No `join-refused`: the room reports a join only in the lobby (onJoin refuses one after it), before any start
1260	      // in the same step, and seats no more players than the flow has seats (docs/match-online-coverage.md).
1261	      case "phase-changed":
1262	        // §2: once the ready countdown starts, admission refuses late arrivals; back in the lobby, it admits again.
1263	        if (event.to === "ready" || event.to === "lobby") void this.setMatchmaking({ metadata: { code: this.state.code, custom: privateMatch.custom, started: event.to === "ready" } });
1264	        return;
1265	      case "control-started":
1266	        this.startControl(event.tick);
1267	        return;
1268	      case "match-ended":
1269	        this.endMatch(event.results);
1270	        return;
1271	      default:
1272	        return;
1273	    }
1274	  }
1275	
1276	  /**
1277	   * §2's control start: every ship present gets the encounter rules' departure protection from this tick, the claim
1278	   * config's deadline counts from it (the timer's end), and the reveals' clocks start. The accomplishments start from
1279	   * the first tick in play, which records where each rubbing is and each balance (the starting gold).
1280	   */
1281	  private startControl(tick: number): void {
1282	    // Every ship's player is in the match (the room's invariant): a leave removes the ship at once.
1283	    const ids = this.simulation.ships.map((ship) => ship.id);
1284	    this.encounters = createEncounterState(this.encounterConfig, { tick, spawnProtected: ids });
1285	    this.claimConfig = claimConfigFor(this.tuning, this.finalIsland.claimPoint, tick, this.config.map);
