1291	  /**
1292	   * The match is over (§2, §5): outcomes freeze. A duel still running ends without theft (§2), each fighter's lobby
1293	   * showing the cancellation for a moment; the ships stop taking input; the results are the flow's, recorded once.
1294	   */
1295	  private endMatch(results: MatchResults): void {
1296	    const tick = results.tick;
1297	    for (const duel of this.seaDuels.values()) {
1298	      if (findDuel(this.ledger, duel.id)?.phase === "fighting" && tick >= this.ledger.tick) {
1299	        this.ledgerStep("reportDuelResult", reportDuelResult(this.ledger, { duelId: duel.id, tick, outcome: "cancelled" }));
