1394	   * (a) the buyer's ship is not moored at a dock now (or waits out of the world to respawn); (b) the ledger has them
1395	   * disconnected, in a duel (fighting or in its choice window), or short of the rumor's price; (c) there is no lead to
1396	   * sell (`targetedRumorAvailability`: covered, capped or none). A request waits only while its player is in the match.
1397	   */
1398	  private rumorRefusal(config: IntelConfig, intel: IntelState, view: IntelWorldView, playerId: string, request: PendingRumor): RumorRefusalName | undefined {
1399	    const ship = this.simulation.ships.find((each) => each.id === playerId)!;
1400	    const waiting = this.encounters.players.find((each) => each.id === playerId)?.respawn != null;
1401	    if (ship.dock === NOT_DOCKED || waiting) return "not-at-dock";
1402	    const player = findPlayer(this.ledger, playerId)!;
1403	    if (player.status === "disconnected") return "player-disconnected";
1404	    if (activeDuelOf(this.ledger, playerId) !== undefined) return "player-in-duel";
1405	    if (player.gold < itemPrice(this.ledger.rules, "rumor")) return "insufficient-gold";
1406	    const offer = targetedRumorAvailability(config, intel, view, playerId, request.type);
1407	    return offer === "rumor" || offer === "sighting" ? undefined : offer;
1408	  }
1409	
1410	  /** A purchase request decided: kept for replays, and answered to its player (a bought lead was just delivered). */
1411	  private decideRumor(playerId: string, request: PendingRumor, decision: RumorDecision): void {
1412	    this.rumors.decide(playerId, request.requestId, decision);
1413	    this.clients.get(playerId)?.send(JournalMessageType.RumorResult, rumorResult(request.requestId, decision, false));
1414	  }
