1417	   * §11: a player asks for a targeted rumor. Rate-capped and validated. A request id the room already decided for this
1418	   * player is answered from its record first, whatever else holds now: a bought one resends its lead, a refused one the
1419	   * same refusal. Otherwise, while the match runs, it waits for a world tick: merged into a pending request with its
1420	   * id, or refused `busy` when two already wait.
1421	   */
1422	  private receiveBuyRumor(sessionId: string, message: unknown): void {
1423	    const frame = this.simulation.frame;
1424	    const rate = this.rumorRate.get(sessionId) ?? { windowStart: frame, count: 0 };
1425	    if (frame - rate.windowStart >= STEPS_PER_SECOND) {
1426	      rate.windowStart = frame;
1427	      rate.count = 0;
