1430	    this.rumorRate.set(sessionId, rate);
1431	    if (rate.count > MAX_BUY_RUMOR_PER_SECOND) return;
1432	    const request = validateBuyRumorMessage(message);
1433	    if (request !== undefined) this.arriveRumor(sessionId, request);
1434	  }
1435	
