1437	    const client = this.clients.get(sessionId);
1438	    const earlier = this.rumors.decided(sessionId, request.requestId);
1439	    if (earlier !== undefined) {
1440	      if (earlier.outcome === "bought") client?.send(JournalMessageType.Lead, earlier.lead);
1441	      client?.send(JournalMessageType.RumorResult, rumorResult(request.requestId, earlier, true));
1442	      return;
1443	    }
1444	    if (!this.inPlay()) {
1445	      client?.send(JournalMessageType.RumorResult, rumorResult(request.requestId, { outcome: "refused", type: request.type, reason: "not-in-play" }, false));
1446	      return;
1447	    }
