1449	    if (arrival === "busy") client?.send(JournalMessageType.RumorResult, rumorResult(request.requestId, { outcome: "refused", type: request.type, reason: "busy" }, false));
1450	  }
1451	
1452	  /**
1453	   * The world as the intel module reads it: every player in the match at their ship, and every rubbing where the
1454	   * ledger has it. A player who left while a duel still reserves their rubbings stays in the view, at the position
1455	   * they left from, until that duel settles.
1456	   */
1457	  private intelView(tick: number): IntelWorldView {
1458	    const ships = new Map(this.simulation.ships.map((ship) => [ship.id, ship]));
1459	    const holding = new Set(this.ledger.rubbings.flatMap((rubbing) => (rubbing.location.kind === "duel" ? [rubbing.location.playerId] : [])));
1460	    const players = this.ledger.players.flatMap((player) => {
1461	      const ship = ships.get(player.id);
