import { encounterRules } from "@pirate-sea-race/content/encounters";
import type { MatchTuning } from "@pirate-sea-race/server";
import { findPlayer, heldTypes, type LedgerState } from "@pirate-sea-race/simulation/objectives";
import type { HeadlessClient, HeadlessClientOptions } from "@pirate-sea-race/test-tools";
import { EAST, HUB_X, OPEN_ROW, playersAt, quickStart, roomOf, TEST_SOURCE_LAYOUT, WEST, type Seat } from "./seaDuelSetup.js";

/**
 * What the rubbing tests share (`rubbings*.test.ts`). Colyseus has one matchmaker per process, so a test file's server
 * gives every match in that file the same timings: each file picks its own `MatchTuning`, all with the test source
 * layout, and asserts in world ticks.
 */

export const layout = TEST_SOURCE_LAYOUT.map((types) => [...types]);

/**
 * Encounter timings that keep a theft test to seconds: a 4 s ready check (so a fighter who never readies loses by
 * forfeit quickly), a 2 s respawn wait, and 5 s of protection after a win or a respawn. The ready check still ends
 * after the 3 s countdown.
 */
export const quickEncounters = { ...encounterRules, readyTimeoutTicks: 80, respawnDelayTicks: 40, winProtectionTicks: 100, respawnProtectionTicks: 100 };

/** A fighter away from a duel forfeits after 3 s instead of 10 s. */
export const QUICK_ABSENCE_TICKS = 60;

export function tuned(tuning: Partial<MatchTuning>): Partial<MatchTuning> {
  return quickStart({ sourceLayout: layout, encounters: quickEncounters, duelAbsenceTicks: QUICK_ABSENCE_TICKS, ...tuning });
}

/** The host west and the guest east on the open row, in grapple range, the host facing the guest. */
export const HOST_SEAT: Seat = { tileX: HUB_X - 3, tileY: OPEN_ROW, heading: EAST };
export const GUEST_SEAT: Seat = { tileX: HUB_X + 3, tileY: OPEN_ROW, heading: WEST };

export async function placePair(endpoint: string, host: HeadlessClient, guest: HeadlessClient): Promise<void> {
  await host.placeShip(endpoint, HOST_SEAT);
  await guest.placeShip(endpoint, GUEST_SEAT);
  await host.waitFor(() => host.ship(guest.sessionId) !== undefined);
}

export const ledgerOf = (client: HeadlessClient): LedgerState => roomOf(client).ledgerState;
export const ledgerPlayer = (client: HeadlessClient, id = client.sessionId) => findPlayer(ledgerOf(client), id);
export const lastDuel = (client: HeadlessClient) => ledgerOf(client).duels.at(-1);
/** The types a player holds in the ledger, reserved ones included. */
export const holds = (client: HeadlessClient, id: string) => heldTypes(ledgerOf(client), id);
export const shipOf = (client: HeadlessClient, id: string) => roomOf(client).matchState.ships.find((ship) => ship.id === id);

/** Two players in one match on their seats, the guest's client with its own options (never ready: it loses by forfeit). */
export async function pair(
  endpoint: string,
  track: (client: HeadlessClient) => void,
  guest: HeadlessClientOptions = {},
  endpoints?: readonly string[],
): Promise<{ host: HeadlessClient; guest: HeadlessClient }> {
  const [host, other] = (await playersAt(endpoint, [HOST_SEAT, GUEST_SEAT], track, { clients: [{}, guest], ...(endpoints ? { endpoints } : {}) })) as [HeadlessClient, HeadlessClient];
  return { host, guest: other };
}
import { expect } from "vitest";
import { seaMap } from "@pirate-sea-race/content";
import { claimRules } from "@pirate-sea-race/content/claim";
import { intelRules } from "@pirate-sea-race/content/intel";
import { finalIslandOf, type MatchTuning } from "@pirate-sea-race/server";
import { defaultSimulationConfig, hullPathIsClear, tileCentre } from "@pirate-sea-race/simulation";
import { objectiveRules } from "@pirate-sea-race/simulation/objectives";
import type { HeadlessClient } from "@pirate-sea-race/test-tools";
import { quickEncounters } from "./rubbingsSetup.js";
import { collectAt, dockFor, NORTH, openWater, quickStart, roomOf, SOUTH, TEST_SOURCE_LAYOUT, type Seat } from "./seaDuelSetup.js";

/**
 * What the match-flow tests share (`lobby`, `reveals`, `claim` and `endings`): the pinned final island, the seats
 * around its claim tile, and the test-only tunings each file starts its server with (one per file: Colyseus has one
 * matchmaker per process). Every tuning deals the test source layout (Suns on Palm Key and Old Stones, Moons on Ember
 * Rock and Mist Cay) and pins the final-socket secret, so a test knows where the treasure is.
 */

/** The pinned final-socket secret (test-only), and the island it picks. */
export const PINNED_FINAL_SECRET = 3;
export const FINAL = finalIslandOf(seaMap, PINNED_FINAL_SECRET);
const socket = seaMap.finalSockets[FINAL.socket]!;
/** The claim tile: its centre is the claim point, the treasure circle's centre. */
export const CLAIM_TILE = socket.claimTile;
/** Which way the claim tile lies from its islet: a challenger comes from further out on that side. */
const outward = CLAIM_TILE.tileY >= socket.rect.tileY + socket.rect.heightTiles ? 1 : -1;
/** A ship stopped on the claim tile, facing out to sea. */
export const CLAIM_SEAT: Seat = { tileX: CLAIM_TILE.tileX, tileY: CLAIM_TILE.tileY, heading: outward > 0 ? SOUTH : NORTH };
/** A challenger four tiles further out, facing the claim tile: in grapple range and in the aim. */
export const CHALLENGER_SEAT: Seat = { tileX: CLAIM_TILE.tileX, tileY: CLAIM_TILE.tileY + 4 * outward, heading: outward > 0 ? NORTH : SOUTH };

/** Checks the seats: open water, and a clear line from the challenger to the claim tile. */
export function expectClaimSeats(): void {
  expect(openWater(CLAIM_SEAT, CLAIM_SEAT)).toBe(true);
  expect(openWater(CHALLENGER_SEAT, CHALLENGER_SEAT)).toBe(true);
  const [from, to] = [tileCentre(defaultSimulationConfig, CHALLENGER_SEAT.tileX, CHALLENGER_SEAT.tileY), tileCentre(defaultSimulationConfig, CLAIM_SEAT.tileX, CLAIM_SEAT.tileY)];
  expect(hullPathIsClear(defaultSimulationConfig, from.x, from.y, to.x, to.y)).toBe(true);
  expect(tileCentre(defaultSimulationConfig, CLAIM_TILE.tileX, CLAIM_TILE.tileY)).toEqual(FINAL.claimPoint);
}

/**
 * A tuning for the match-flow tests: the test source layout, the pinned final socket, one-second holds, quick duels
 * (a 4 s ready check, a 2 s respawn), matches that start at once through the lobby, and the room's test hooks. The
 * claim, intel and other settings are the file's own.
 */
export function flowTuning(tuning: Partial<MatchTuning> = {}): Partial<MatchTuning> {
  const base = quickStart(
    {
      sourceLayout: TEST_SOURCE_LAYOUT.map((types) => [...types]),
      finalSocketSecret: PINNED_FINAL_SECRET,
      objectives: { ...objectiveRules, collectTicks: 20, cacheClaimTicks: 20 },
      claim: claimRules,
      intel: intelRules,
      testHooks: true,
    },
    quickEncounters,
  );
  return { ...base, ...tuning };
}

/** Collects a Sun at Palm Key and a Moon at Ember Rock: every type of the slice, a full set. */
export async function collectFullSet(client: HeadlessClient, endpoint: string): Promise<void> {
  await collectAt(client, endpoint, dockFor("sun"), "sun");
  await collectAt(client, endpoint, dockFor("moon"), "moon");
  expect(client.rubbings()).toEqual(["sun", "moon"]);
}

/** The flow's control start tick of a client's match. */
export const controlStartOf = (client: HeadlessClient): number => roomOf(client).flowState.controlStartTick!;
import { afterAll, beforeAll, describe, expect, it } from "vitest";
import { isNavigable, seaMap } from "@pirate-sea-race/content";
import { JournalMessageType, journalMessageSchema, MAX_BUY_RUMOR_PER_SECOND, type JournalMessage } from "@pirate-sea-race/protocol";
import { startGameServer, type MatchRoom, type RunningGameServer } from "@pirate-sea-race/server";
import { objectiveRules } from "@pirate-sea-race/simulation/objectives";
import { HeadlessClient, ImpairmentProxy, sleep, type Movement } from "@pirate-sea-race/test-tools";
import { GUEST_SEAT, HOST_SEAT, placePair, tuned } from "./rubbingsSetup.js";
import { collectAt, containsText, HOLD_E, HUB_X, OPEN_ROW, openWater, playersAt, roomOf, startThroughLobby, tracker, until, EAST, type Seat } from "./seaDuelSetup.js";

/**
 * §3 and §11's intel through the real room: start rumors, fresh and replacement leads, the journal log in each player's
 * own status, and targeted rumor purchases, read from what the headless clients received (and, for §16, from their raw
 * frames). Every island seals one Sun and one Moon here (test-only), so collecting an island's Sun leaves a rumor about
 * it stale. Players start with 40 gold (test-only), so one rumor (25) is affordable and a second is not. The rooms check
 * `checkLedger` (the gold identity among it) and their own invariant after every world tick (`tracker`). Cases that
 * need one exact tick line requests up with the room's test hooks (`testBuyRumor`, `stepWorldTicks`) while the clock is
 * paused.
 */
const LAYOUT = [
  ["sun", "moon"],
  ["sun", "moon"],
  ["sun", "moon"],
  ["sun", "moon"],
];
const GOLD = 40;
const PRICE = objectiveRules.rumorPrice;
let server: RunningGameServer;
let endpoint: string;

beforeAll(async () => {
  const matchTuning = tuned({
    sourceLayout: LAYOUT,
    objectives: { ...objectiveRules, collectTicks: 20, cacheClaimTicks: 20, startingGold: GOLD },
    testHooks: true,
  });
  server = await startGameServer({ port: 0, host: "127.0.0.1", handleSignals: false, testPlacement: true, matchTuning });
  endpoint = `http://127.0.0.1:${server.port}`;
});

afterAll(async () => {
  await server.close();
});

/** Open water in a row south of the hub, one seat per player, out of every dock's way. */
const seat = (index: number): Seat => ({ tileX: HUB_X - 8 + index * 4, tileY: OPEN_ROW, heading: EAST });
const dockOf = (island: number, which = 0) => seaMap.docks.filter((dock) => dock.island === island)[which]!;

/** Open water `distance` tiles from a dock, in a straight clear line from it, facing the dock (a grapple's aim). */
function seatOff(dock: { tileX: number; tileY: number }, distance: number): Seat {
  for (const [dx, dy] of [
    [-1, 0],
    [1, 0],
    [0, -1],
    [0, 1],
  ] as const) {
    const at = { tileX: dock.tileX + dx * distance, tileY: dock.tileY + dy * distance, heading: 0 };
    if (!isNavigable(seaMap, at.tileX, at.tileY) || !openWater(at, { ...dock, heading: 0 })) continue;
    return { ...at, heading: (Math.round((Math.atan2(-dy, -dx) / (2 * Math.PI)) * 64) + 64) % 64 };
  }
  throw new Error(`no open water ${distance} tiles off dock ${dock.tileX},${dock.tileY}`);
}

async function moor(client: HeadlessClient, dock: { id: number; tileX: number; tileY: number }): Promise<void> {
  await client.placeShip(endpoint, { tileX: dock.tileX, tileY: dock.tileY, heading: 0 });
  await client.holdUntil(HOLD_E, () => client.ship()?.dock === dock.id, 5000);
}

/** The player's start rumor, once it arrived. */
async function startRumor(client: HeadlessClient): Promise<Extract<JournalMessage, { kind: "rumor" }>> {
  await client.waitFor(() => client.leads.some((lead) => lead.kind === "rumor" && lead.reason === "start"));
  return client.leads.find((lead) => lead.kind === "rumor" && lead.reason === "start") as Extract<JournalMessage, { kind: "rumor" }>;
}

/** The ledger's purchases for a player. */
const purchasesOf = (room: MatchRoom, id: string) => room.ledgerState.requests.filter((outcome) => outcome.kind === "purchase" && outcome.playerId === id);
const goldOf = (room: MatchRoom, id: string) => room.ledgerState.players.find((player) => player.id === id)!.gold;

/** Holds the room's clock after the current world tick. */
async function pause(room: MatchRoom): Promise<void> {
  room.pauseAfterTick(room.matchState.worldTick);
  await until(() => room.worldPaused, 2000, "the pause");
}

/** The targeted leads a player received (rumors, or sighting entries, bought), each once (a replay resends its lead). */
const targetedLeads = (client: HeadlessClient) =>
  [...new Map(client.leads.map((lead) => [JSON.stringify(lead), lead])).values()].flatMap((lead) =>
    lead.kind === "rumor" && lead.reason === "targeted" ? [lead.type] : lead.kind === "carrier-sighting" ? lead.sightings.filter((each) => each.reason === "targeted").map((each) => each.type) : [],
  );

describe.concurrent("rumors and the journal (§3, §11)", () => {
  it("gives every player a start rumor at control start: an island with a sealed source of a type they lack, never a carrier; the journal and the offers show it", async ({ onTestFinished }) => {
    const track = tracker(onTestFinished);
    const clients = await playersAt(endpoint, [seat(0), seat(1), seat(2)], track);
    const room = roomOf(clients[0]!);
    const controlStart = room.flowState.controlStartTick!;
    for (const client of clients) {
      const rumor = await startRumor(client);
      expect(rumor.tick).toBe(controlStart);
      expect(rumor.entry).toBe(1);
      // No cache exists yet, so it names an island, where a source of that type is still sealed.
      expect(rumor.target.kind).toBe("island");
      const island = rumor.target.kind === "island" ? rumor.target.island : -1;
      expect(rumor.target.name).toBe(seaMap.islands[island]!.name);
      const sealed = room.ledgerState.rubbings.filter((rubbing) => rubbing.location.kind === "source" && rubbing.type === rumor.type);
      expect(sealed.some((rubbing) => rubbing.location.kind === "source" && room.ledgerState.sources.find((source) => source.id === (rubbing.location as { sourceId: string }).sourceId)!.island === island)).toBe(true);
      expect(client.rubbings()).not.toContain(rumor.type);
      // One lead each, and never a carrier.
      expect(client.leads).toHaveLength(1);
      expect(client.leads.some((lead) => lead.kind === "carrier-sighting")).toBe(false);
