export const TELEGRAPH_COLOR = 0xffd0a0;
/** A duel marker's crossed swords. */
export const MARKER_COLOR = 0xc0c8d0;
/** The ring of a protected ship (§6's escape protection). */
export const PROTECTION_COLOR = 0x7fdbff;
/** A recovery cache's chest (§12) and its trim. */
export const CACHE_COLOR = 0xd4a017;
export const CACHE_TRIM = 0x3a2a10;
/** §9: a fruit pedestal's stone, and the fruit on it while it is full. */
export const PEDESTAL_COLOR = 0x8f8a80;
export const FRUIT_COLOR = 0xff7a1a;
/** §5: the treasure (the route's circle, its minimap mark, a claimer's ring). */
export const TREASURE_COLOR = 0xffd24a;

/** §3's sector borders and the sector's name, faint over the sea. */
export const SECTOR_COLOR = 0xe8d9a8;
import { cssColor, slotColor, type MatchView } from "./matchView.js";
import { treasureView, type TreasureGeometry } from "./treasureView.js";
import {
  AIM_COLOR,
  CACHE_COLOR,
  CACHE_TRIM,
  DOCK_COLOR,
  DOCK_PLANK,
  FOG_COLOR,
  FRUIT_COLOR,
  GRID_COLOR,
  INCOMING_COLOR,
  SECTOR_COLOR,
  LAND_COLORS,
  MARKER_COLOR,
  OWN_RING_COLOR,
  PEDESTAL_COLOR,
  PROTECTION_COLOR,
  SEA_COLOR,
  SHOAL_COLOR,
  SHOAL_FLECK,
  SIGHT_COLOR,
  TELEGRAPH_COLOR,
 * Draws the sea: the tile map from content, the ships the server sent at interpolated positions, a camera that
 * follows the player's ship, the sight circle, and a minimap whose fog clears along the player's path. The encounters
