    const sent: [string, unknown][] = [];
    const views: ShopView[] = [];
    const focus: boolean[] = [];
    // The journal the page runs: the shop's rumor buttons are its buttons, and its Buy is theirs.
    const journal = new JournalPanel(
      (type, message) => sent.push([type, message]),
      () => undefined,
      () => undefined,
      () => undefined,
      (island) => `Island ${island}`,
    );
    journal.update(rumorStatus, 10);
    const shop = new ShopPanel(
      (type, message) => sent.push([type, message]),
      (view) => views.push(view),
      (backwards) => focus.push(backwards),
      {
        get status() {
          return journal.currentStatus;
        },
        get pendingType() {
          return journal.pendingType;
        },
        buy: (type) => journal.buy(type),
      },
    );
    return { shop, journal, sent, focus, last: () => views.at(-1)! };
  };
  const key = (code: string, repeat = false, shiftKey = false) => ({ code, repeat, shiftKey });

  it("opens on B only where the ship is moored, closes on B or Escape, moves focus on Tab, and ignores B's auto-repeat", () => {
    const { shop, focus, last } = panel();
    shop.update(status({ moored: false }), 10);
    expect(shop.keydown(key("KeyB"))).toBe(false);
    expect(shop.isOpen).toBe(false);
    shop.update(status(), 11);
    expect(shop.keydown(key("KeyB"))).toBe(true);
    expect(shop.isOpen).toBe(true);
    expect(last().hidden).toBe(false);
    expect(focus).toEqual([false]);
    expect(shop.keydown(key("KeyB", true))).toBe(true);
    expect(shop.isOpen).toBe(true);
    expect(shop.keydown(key("Tab", false, true))).toBe(true);
    expect(focus).toEqual([false, true]);
    expect(shop.keydown(key("KeyW"))).toBe(false);
    expect(shop.keydown(key("Escape"))).toBe(true);
    expect(shop.isOpen).toBe(false);
    // Closed, Escape and Tab are not its keys.
    expect(shop.keydown(key("Escape"))).toBe(false);
    expect(shop.keydown(key("Tab"))).toBe(false);
    shop.keydown(key("KeyB"));
    shop.keydown(key("KeyB"));
    expect(shop.isOpen).toBe(false);
  });

  it("is no safe zone: casting off or a grapple (the status leaves the dock) closes it", () => {
    const { shop, last } = panel();
    shop.update(status(), 10);
    shop.toggle();
    expect(shop.isOpen).toBe(true);
    shop.update(status({ moored: false }), 11);
    expect(shop.isOpen).toBe(false);
    expect(last().hidden).toBe(true);
    shop.update(status(), 12);
    shop.toggle();
    shop.update(undefined, 13);
    expect(shop.isOpen).toBe(false);
  });

  it("sends buy-tonic with a fresh id from an available button only, holds it until the answer, and shows the answer", () => {
    const { shop, sent, last } = panel();
    shop.update(status(), 10);
    shop.buyTonic();
    expect(sent).toEqual([[ShopMessageType.BuyTonic, { requestId: "b1" }]]);
    expect(last().tonic.state).toBe("pending");
    // Pending: a second press sends nothing.
    shop.buyTonic();
    expect(sent).toHaveLength(1);
    // Another request's answer (or a malformed one) leaves it pending.
    shop.purchased({ requestId: "b9", outcome: "bought", price: 30, tonics: 1, replayed: false });
    shop.purchased({ requestId: "b1", outcome: "bought" });
    expect(last().tonic.state).toBe("pending");
    shop.purchased({ requestId: "b1", outcome: "bought", price: 30, tonics: 1, replayed: false });
    shop.update(status({ gold: 20, tonics: 1 }), 11);
    expect(last().tonic).toMatchObject({ state: "gold", disabled: true });
    expect(last().message.text).toBe("Bought a sail tonic (−30 gold): you carry 1 of 2");
    shop.buyTonic();
    expect(sent).toHaveLength(1);
    // A request with no answer (dropped by the rate cap) stops holding the button after five seconds.
    shop.update(status({ gold: 60, tonics: 1 }), 12);
    shop.buyTonic();
    shop.update(status({ gold: 60, tonics: 1 }), 12 + 100);
    expect(last().tonic.state).toBe("pending");
    shop.update(status({ gold: 60, tonics: 1 }), 12 + 101);
    expect(last().tonic.state).toBe("available");
  });

  it("sells the targeted rumor through the journal's own purchase: the same buy-rumor, the same pending state, and shows its answer", () => {
    const { shop, journal, sent, last } = panel();
    shop.update(status(), 10);
    expect(last().rumors.map((button) => [button.type, button.state])).toEqual([
      ["sun", "available"],
      ["moon", "no-lead"],
    ]);
    shop.buyRumor("sun");
    expect(sent).toEqual([[JournalMessageType.BuyRumor, { requestId: "j1", type: "sun" }]]);
    expect(journal.pendingType).toBe("sun");
    expect(last().rumors[0]!.state).toBe("pending");
    // A disabled button sends nothing, from either panel.
    shop.buyRumor("moon");
    expect(sent).toHaveLength(1);
    const answer: RumorResultMessage = { requestId: "j1", type: "sun", outcome: "refused", reason: "not-at-dock", replayed: false };
    journal.result(answer);
    shop.rumorResult(answer);
    expect(last().message).toEqual({ text: "Sun: Moor at a dock to buy a rumor, nothing charged", state: "not-at-dock" });
    expect(last().rumors[0]!.state).toBe("available");
  });

  it("takes the page's keys one panel at a time: B opens nothing over the journal, the ruin or the fruit panel, and M nothing over the shop", () => {
    const closed: KeyPanel = { isOpen: false, keydown: () => false };
    const open: KeyPanel = { isOpen: true, keydown: () => false };
    const event = (code: string, target: unknown = {}) => ({ code, repeat: false, target: target as EventTarget });
    const { shop } = panel();
    shop.update(status(), 10);
    expect(panelKeydown(event("KeyB"), { ruins: closed, fruit: closed, journal: closed, shop })).toBe(true);
    expect(shop.isOpen).toBe(true);
    // Open, only its keys count: M does not open the journal over it.
    const journal = panel().journal;
    expect(panelKeydown(event("KeyM"), { ruins: closed, fruit: closed, journal, shop })).toBe(false);
    expect(journal.isOpen).toBe(false);
    expect(panelKeydown(event("Escape"), { ruins: closed, fruit: closed, journal, shop })).toBe(true);
    expect(shop.isOpen).toBe(false);
    for (const others of [
      { ruins: open, fruit: closed, journal: closed },
      { ruins: closed, fruit: open, journal: closed },
      { ruins: closed, fruit: closed, journal: open },
    ]) {
      expect(panelKeydown(event("KeyB"), { ...others, shop })).toBe(false);
      expect(shop.isOpen).toBe(false);
    }
    expect(panelKeydown(event("KeyB", { tagName: "INPUT" }), { ruins: closed, fruit: closed, journal: closed, shop })).toBe(false);
    expect(shop.isOpen).toBe(false);
  });
});

describe("T drinks a tonic (TonicKey)", () => {
  it("sends one use-tonic per key press with a fresh id, never on auto-repeat or into a text field, and keeps the last answer", () => {
    const sent: [string, unknown][] = [];
    const tonic = new TonicKey((type, message) => sent.push([type, message]));
    const press = (repeat = false, target: unknown = {}) => tonic.keydown({ code: "KeyT", repeat, target: target as EventTarget });
    expect(press()).toBe(true);
    // Held down: the auto-repeat sends nothing.
    for (let each = 0; each < 5; each++) expect(press(true)).toBe(true);
    expect(sent).toEqual([[ShopMessageType.UseTonic, { requestId: "t1" }]]);
    expect(press()).toBe(true);
    expect(sent.at(-1)).toEqual([ShopMessageType.UseTonic, { requestId: "t2" }]);
    expect(press(false, { tagName: "INPUT" })).toBe(false);
    expect(tonic.keydown({ code: "KeyR", repeat: false, target: null })).toBe(false);
    expect(sent).toHaveLength(2);
    expect(tonic.last).toBeUndefined();
    tonic.used({ requestId: "t2", outcome: "refused", reason: "grappled", replayed: false });
    tonic.used({ requestId: "t3", outcome: "sideways" });
    expect(tonic.last).toEqual({ requestId: "t2", outcome: "refused", reason: "grappled", replayed: false });
  });
});

describe("supply crates on the sea", () => {
  it("draws each crate in sight at its point and reports its id; the view keeps only those the server sent, in id order", () => {
    const view = new MatchView("me");
    view.ingestCrates(
      new Map([
        ["crate-2", { x: 10112, y: 17792 }],
        ["crate-0", { x: 10112, y: 10624 }],
      ]).entries(),
    );
    expect(view.crates()).toEqual([
      { id: "crate-0", x: 10112, y: 10624 },
      { id: "crate-2", x: 10112, y: 17792 },
    ]);
    const drawn: { x: number; y: number; half: number }[] = [];
    const reported = drawCrates({ crate: (x, y, half) => drawn.push({ x, y, half }) }, view.crates(), { x: 100, y: 50 });
    const pixels = (subUnits: number) => (subUnits * TILE_PIXELS) / 256;
    expect(drawn).toEqual([
      { x: pixels(10112), y: pixels(10624), half: CRATE_HALF },
      { x: pixels(10112), y: pixels(17792), half: CRATE_HALF },
    ]);
    expect(reported).toEqual([
      { id: "crate-0", x: Math.round(pixels(10112) - 100), y: Math.round(pixels(10624) - 50) },
      { id: "crate-2", x: Math.round(pixels(10112) - 100), y: Math.round(pixels(17792) - 50) },
    ]);
    // A claimed crate leaves the server's view: it is drawn no more.
    view.ingestCrates(new Map([["crate-2", { x: 10112, y: 17792 }]]).entries());
    expect(drawCrates({ crate: () => undefined }, view.crates(), { x: 0, y: 0 }).map((crate) => crate.id)).toEqual(["crate-2"]);
  });
});

