test("holds E through a 400 ms pause of the page's own sends mid-collection, and the six-second collection completes without starting over", async ({ browser, page, request }) => {
  test.setTimeout(90_000);
  // Every message the page sends goes through here; while `pausedUntil` is ahead, they wait and then go in order, as a
  // stalled connection would deliver them.
  let pausedUntil = 0;
  const held: (string | Buffer)[] = [];
  let upstream: { send(message: string | Buffer): void } | undefined;
  const flush = () => {
    while (held.length > 0) upstream?.send(held.shift()!);
  };
  await page.routeWebSocket(
    (url) => url.port === "2593",
    (ws) => {
      const server = ws.connectToServer();
      upstream = server;
      ws.onMessage((message) => {
        if (Date.now() < pausedUntil) {
          held.push(message);
          return;
        }
        flush();
        server.send(message);
      });
    },
  );
  const code = await createMatch(page);
  const companion = await startWithCompanion(browser, page, code);
  try {
    await place(request, page, code, PALM_WEST.tileX, PALM_WEST.tileY, WEST);
    await page.keyboard.press("e");
    await expect(page.getByTestId("hud-dock")).toHaveAttribute("data-dock", String(PALM_WEST.id));
    // Every hold progress the page shows from now on.
    await page.evaluate(() => {
      const bar = document.querySelector<HTMLElement>('[data-testid="hud-hold-progress"]')!;
      const seen: number[] = [];
      (window as unknown as { __held: number[] }).__held = seen;
      new MutationObserver(() => seen.push(Number(bar.dataset["held"]))).observe(bar, { attributes: true, attributeFilter: ["data-held"] });
    });
    await page.keyboard.down("e");
    try {
      await expect(page.getByTestId("hud-hold")).toHaveAttribute("data-state", "collect:sun");
      await expect.poll(async () => Number(await page.getByTestId("hud-hold-progress").getAttribute("data-held"))).toBeGreaterThanOrEqual(40);
      // Two seconds in, the page's sends stop for 400 ms (E still down), then go on.
      pausedUntil = Date.now() + 400;
      setTimeout(flush, 450);
      await expect(page.getByTestId("purse-rubbings")).toHaveAttribute("data-types", "sun", { timeout: 12_000 });
    } finally {
      await page.keyboard.up("e");
    }
    // The progress never went back: one hold from start to finish.
    const progress = await page.evaluate(() => (window as unknown as { __held: number[] }).__held);
    expect(progress.length).toBeGreaterThan(10);
    const drops = progress.filter((value, index) => index > 0 && value < progress[index - 1]! && value !== 0);
    expect(drops).toEqual([]);
    expect(progress.slice(0, progress.lastIndexOf(0) === -1 ? progress.length : progress.lastIndexOf(0))).not.toContain(0);
    await expect(page.getByTestId("hud-result")).toContainText(/Sun/);
  } finally {
    await companion.close();
  }
});

